(()=>{'use strict';
const $=s=>document.querySelector(s),tiers=['S','A','B','C','D','미배치'],colors=['#d86f86','#e5a64f','#6e9bd2','#7eae87','#a49baa','#64748b'],units=CoopData.demonsIn('supreme'),slugs=new Set(units.map(d=>d.slug)),key='stack-lab-personal-tiers-v1',el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};let layout={},selected=null,dict={},blob=null,imageUrl=null;
const name=slug=>{const d=CoopData.DEMON_BY_SLUG.get(slug);return dict[d?.name]||d?.name||slug;};
function restore(){let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}const used=new Set();for(const tier of tiers)layout[tier]=(Array.isArray(saved?.layout?.[tier])?saved.layout[tier]:[]).filter(slug=>{if(!slugs.has(slug)||used.has(slug))return false;used.add(slug);return true;});layout['미배치'].push(...units.map(d=>d.slug).filter(s=>!used.has(s)));$('#personal-tier-title').value=typeof saved?.title==='string'?saved.title.slice(0,60):'';}
function save(){try{localStorage.setItem(key,JSON.stringify({layout,title:$('#personal-tier-title').value}));$('#personal-tier-status').textContent='개인 티어리스트를 이 브라우저에 저장했습니다.';}catch{$('#personal-tier-status').textContent='브라우저 저장을 사용할 수 없습니다. 이미지로 저장해 주세요.';}}
function controls(){const tier=tiers.find(t=>layout[t].includes(selected)),at=tier?layout[tier].indexOf(selected):-1;$('#personal-tier-selection').textContent=selected?name(selected)+' 선택됨 · 이동할 위치를 누르세요.':'캐릭터를 선택하세요.';$('#personal-tier-cancel').disabled=!selected;$('#personal-tier-left').disabled=at<=0;$('#personal-tier-right').disabled=at<0||at>=layout[tier].length-1;}
function move(slug,tier,before){if(!slugs.has(slug)||!tiers.includes(tier)||slug===before)return;for(const t of tiers)layout[t]=layout[t].filter(s=>s!==slug);const at=layout[tier].indexOf(before);if(at<0)layout[tier].push(slug);else layout[tier].splice(at,0,slug);save();render();}
function render(){const board=$('#personal-tier-board');board.replaceChildren();tiers.forEach((tier,i)=>{const row=el('section',undefined,'dealer-tier-row'),label=el('div',undefined,'dealer-tier-label'),list=el('div',undefined,'dealer-tier-cards');label.style.setProperty('--tier-color',colors[i]);label.append(el('b',tier));const target=el('button','여기로 이동','personal-tier-target');target.type='button';target.setAttribute('aria-label',tier+' 티어 끝으로 이동');target.onclick=()=>{if(selected)move(selected,tier);};label.append(target);row.append(label,list);row.addEventListener('dragover',e=>{e.preventDefault();});row.addEventListener('drop',e=>{e.preventDefault();const slug=e.dataTransfer?.getData('text/plain');if(slug)move(slug,tier,e.target.closest('[data-personal-slug]')?.dataset.personalSlug);});for(const slug of layout[tier]){const card=el('button',undefined,'dealer-tier-card personal-tier-card'+(selected===slug?' selected':'')),img=el('img');card.type='button';card.draggable=true;card.dataset.personalSlug=slug;card.setAttribute('aria-pressed',String(selected===slug));card.setAttribute('aria-label',name(slug)+' · '+tier+' 티어');img.src='/assets/units/'+CoopData.DEMON_BY_SLUG.get(slug).img+'.webp';img.alt='';img.draggable=false;card.append(img,el('b',name(slug)));card.onclick=()=>{if(selected&&selected!==slug)move(selected,tier,slug);else{selected=selected===slug?null:slug;render();}};card.addEventListener('dragstart',e=>{selected=slug;e.dataTransfer?.setData('text/plain',slug);controls();});list.append(card);}if(!layout[tier].length)list.append(el('span','캐릭터를 이곳으로 옮기세요.','dealer-tier-empty'));board.append(row);});controls();}
function reorder(delta){if(!selected)return;const tier=tiers.find(t=>layout[t].includes(selected)),list=layout[tier],at=list.indexOf(selected),next=at+delta;if(next<0||next>=list.length)return;[list[at],list[next]]=[list[next],list[at]];save();render();}
const image=src=>new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=src;});
async function exportImage(){const button=$('#personal-tier-image');button.disabled=true;$('#personal-tier-status').textContent='이미지를 만드는 중…';const snapshot=structuredClone(layout),title=$('#personal-tier-title').value.trim()||'나의 초마신 티어리스트';try{await document.fonts?.ready;const width=1200,pad=28,label=100,cardW=124,cardH=110,columns=8,heights=tiers.map(t=>Math.max(90,Math.ceil(snapshot[t].length/columns)*cardH+20)),canvas=document.createElement('canvas');canvas.width=width;canvas.height=140+heights.reduce((a,b)=>a+b,0);const ctx=canvas.getContext('2d');if(!ctx)throw Error('캔버스를 만들 수 없습니다.');ctx.fillStyle='#101827';ctx.fillRect(0,0,width,canvas.height);ctx.fillStyle='#fff';ctx.font='bold 30px sans-serif';ctx.fillText(title,pad,52,width-pad*2);ctx.font='16px sans-serif';ctx.fillStyle='#bec9dd';ctx.fillText('스택 연구소 · 개인 티어리스트 · '+new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date()),pad,86);let y=112;for(let i=0;i<tiers.length;i++){const tier=tiers[i],height=heights[i];ctx.fillStyle='#1c283b';ctx.fillRect(pad,y,width-2*pad,height-6);ctx.fillStyle=colors[i];ctx.fillRect(pad,y,label,height-6);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold 22px sans-serif';ctx.fillText(tier,pad+label/2,y+45);const images=await Promise.all(snapshot[tier].map(slug=>image('/assets/units/'+CoopData.DEMON_BY_SLUG.get(slug).img+'.webp')));snapshot[tier].forEach((slug,j)=>{const x=pad+label+12+(j%columns)*cardW,top=y+10+Math.floor(j/columns)*cardH;if(images[j]){const img=images[j],scale=Math.min(70/img.width,70/img.height);ctx.drawImage(img,x+(cardW-img.width*scale)/2,top,img.width*scale,img.height*scale);}ctx.fillStyle='#fff';ctx.font='14px sans-serif';ctx.fillText(name(slug),x+cardW/2,top+92,cardW-8);});y+=height;}const result=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!result)throw Error('PNG 생성에 실패했습니다.');if(imageUrl)URL.revokeObjectURL(imageUrl);blob=result;imageUrl=URL.createObjectURL(blob);$('#personal-tier-preview').src=imageUrl;$('#personal-tier-download').href=imageUrl;$('#personal-tier-download').download='my-tier-list.png';$('#personal-tier-open').href=imageUrl;let canShare=false;try{canShare=!!navigator.canShare?.({files:[new File([blob],'my-tier-list.png',{type:'image/png'})]});}catch{}$('#personal-tier-share').hidden=!canShare;$('#personal-tier-share-status').textContent='이미지를 길게 눌러 사진에 저장하거나 저장·공유 버튼을 이용하세요.';$('#personal-tier-export').showModal();$('#personal-tier-status').textContent='이미지를 만들었습니다. 미리보기에서 저장하세요.';}catch(error){$('#personal-tier-status').textContent='이미지 저장 실패: '+error.message;}finally{button.disabled=false;}}
$('#personal-tier-title').oninput=save;$('#personal-tier-reset').onclick=()=>{layout=Object.fromEntries(tiers.map(t=>[t,t==='미배치'?units.map(d=>d.slug):[]]));selected=null;save();render();};$('#personal-tier-left').onclick=()=>reorder(-1);$('#personal-tier-right').onclick=()=>reorder(1);$('#personal-tier-cancel').onclick=()=>{selected=null;render();};$('#personal-tier-image').onclick=exportImage;$('#personal-tier-export-close').onclick=()=>$('#personal-tier-export').close();$('#personal-tier-share').onclick=async()=>{if(!blob)return;try{await navigator.share({files:[new File([blob],'my-tier-list.png',{type:'image/png'})],title:'내 티어리스트'});}catch(error){$('#personal-tier-share-status').textContent=error.name==='AbortError'?'공유를 취소했습니다. 파일 저장이나 이미지 길게 누르기를 이용하세요.':'공유할 수 없습니다. 파일 저장이나 새 창 열기를 이용하세요.';}};restore();render();fetch('/ko.json').then(r=>r.json()).then(value=>{dict=value;render();}).catch(()=>{});
})();
